package cloud

import "net/http"

const dashboardHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Arrowhead LocalCloudManager</title><style>
:root{color-scheme:dark;--bg:#07110f;--panel:#10201c;--line:#26433a;--green:#83f3c1;--mint:#c9ffe9;--muted:#8fa9a0;--amber:#ffcb75}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% 5%,#18392f 0,transparent 30%),var(--bg);color:#e8fff6;font:15px/1.5 Inter,ui-sans-serif,system-ui,sans-serif}.shell{max-width:1400px;margin:auto;padding:34px}.top{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:34px}.brand{display:flex;align-items:center;gap:16px}.mark{display:grid;place-items:center;width:52px;height:52px;border:1px solid #3f6d5d;background:#102b24;color:var(--green);font-weight:800;letter-spacing:.08em}.eyebrow{margin:0;color:var(--green);font:700 11px/1.2 ui-monospace,monospace;letter-spacing:.16em;text-transform:uppercase}h1{margin:4px 0 0;font-size:30px;line-height:1.1}.actions{display:flex;align-items:center;gap:12px}.live{display:flex;align-items:center;gap:8px;color:var(--muted)}.dot{width:8px;height:8px;border-radius:50%;background:var(--amber);box-shadow:0 0 0 4px #ffcb7522}.live.ok .dot{background:var(--green);box-shadow:0 0 0 4px #83f3c122}button{border:1px solid #3b6255;background:#153329;color:var(--mint);padding:10px 16px;font-weight:700;cursor:pointer}button:hover{border-color:var(--green)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}.metric,.panel{border:1px solid var(--line);background:linear-gradient(145deg,#11231e,#0b1714);box-shadow:0 18px 45px #0003}.metric{padding:20px}.metric span{display:block;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.08em}.metric strong{display:block;margin-top:6px;color:var(--mint);font-size:34px}.grid{display:grid;grid-template-columns:.9fr 1.4fr;gap:18px}.panel{padding:22px;min-width:0}.panel-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:18px}h2{font-size:18px;margin:3px 0 0}.system-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.system{border:1px solid #24443a;background:#0b1915;padding:14px;min-width:0}.system b{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.system small{color:var(--muted)}.badge{float:right;width:8px;height:8px;border-radius:50%;background:var(--green);margin-top:7px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid #203a32;vertical-align:top}th{color:var(--muted);font-size:11px;letter-spacing:.08em;text-transform:uppercase}td code{color:var(--green);font-size:12px;word-break:break-word}.scroll{max-height:620px;overflow:auto}.error{display:none;padding:13px 16px;margin-bottom:18px;border:1px solid #80493f;background:#321b18;color:#ffd3ca}.empty{color:var(--muted);padding:20px 0}@media(max-width:850px){.shell{padding:20px}.top{align-items:flex-start;flex-direction:column}.metrics,.grid{grid-template-columns:1fr}.system-grid{grid-template-columns:1fr}}
</style></head><body><main class="shell"><header class="top"><div class="brand"><div class="mark">A5</div><div><p class="eyebrow">Eclipse Arrowhead · v5.4.0</p><h1>LocalCloudManager</h1></div></div><div class="actions"><div class="live" id="live"><i class="dot"></i><span>Connecting</span></div><button id="refresh">Refresh</button></div></header><div class="error" id="error"></div><section class="metrics"><article class="metric"><span>Cloud state</span><strong id="state">—</strong></article><article class="metric"><span>Registered systems</span><strong id="system-count">—</strong></article><article class="metric"><span>Service instances</span><strong id="service-count">—</strong></article></section><section class="grid"><article class="panel"><div class="panel-head"><div><p class="eyebrow">System discovery</p><h2>Local-cloud systems</h2></div></div><div class="system-grid" id="systems"></div></article><article class="panel"><div class="panel-head"><div><p class="eyebrow">Service discovery</p><h2>Associated services</h2></div><small id="updated"></small></div><div class="scroll"><table><thead><tr><th>Definition</th><th>Provider</th><th>Version</th><th>Endpoint</th></tr></thead><tbody id="services"></tbody></table></div></article></section></main><script>
'use strict';const auth={'Authorization':'Bearer SYSTEM//LocalCloudManager','Content-Type':'application/json'};const esc=(v)=>String(v??'').replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:auth,body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.errorMessage||('Request failed: '+r.status));return data}function endpoint(s){const i=s.interfaces&&s.interfaces[0];if(!i)return '—';const p=i.properties||{};const a=(p.accessAddresses||[])[0]||'unknown';return (i.protocol||'http').toLowerCase()+'://'+a+':'+(p.accessPort||'—')+(p.basePath||'')}async function load(){const live=document.querySelector('#live'),err=document.querySelector('#error');live.classList.remove('ok');live.lastElementChild.textContent='Refreshing';err.style.display='none';try{const [status,systems,services]=await Promise.all([api('/localcloud/management/status'),api('/localcloud/management/systems'),api('/localcloud/management/services')]);document.querySelector('#state').textContent=status.status||'AVAILABLE';document.querySelector('#system-count').textContent=systems.count??systems.entries?.length??0;document.querySelector('#service-count').textContent=services.count??services.entries?.length??0;document.querySelector('#systems').innerHTML=(systems.entries||[]).map((s)=>'<div class="system"><i class="badge"></i><b>'+esc(s.name)+'</b><small>'+esc(s.version||'unknown')+' · '+esc((s.addresses||[]).map((a)=>a.address).join(', '))+'</small></div>').join('')||'<p class="empty">No systems registered.</p>';document.querySelector('#services').innerHTML=(services.entries||[]).map((s)=>'<tr><td><b>'+esc(s.serviceDefinition?.name)+'</b></td><td>'+esc(s.provider?.name)+'</td><td>'+esc(s.version)+'</td><td><code>'+esc(endpoint(s))+'</code></td></tr>').join('')||'<tr><td colspan="4" class="empty">No services registered.</td></tr>';document.querySelector('#updated').textContent='Updated '+new Date().toLocaleTimeString();live.classList.add('ok');live.lastElementChild.textContent='Live';}catch(e){err.textContent=e.message;err.style.display='block';live.lastElementChild.textContent='Degraded'}}document.querySelector('#refresh').addEventListener('click',load);load();setInterval(load,15000);
</script></body></html>`

func serveDashboard(w http.ResponseWriter) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Content-Security-Policy", "default-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; img-src 'self' data:")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte(dashboardHTML))
}
